// ========== src\core\Camera.h ==========

#pragma once

#include <cmath>
#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>
#include <glm/gtc/quaternion.hpp>

namespace core {

class Camera {
 public:
  void Rotate(float dx, float dy, float sensitivity = 0.1f) {
    yaw_ += dx * sensitivity;
    pitch_ -= dy * sensitivity;
    pitch_ = glm::clamp(pitch_, -89.0f, 89.0f);

    forward_ = glm::normalize(glm::vec3(cosf(glm::radians(yaw_)) * cosf(glm::radians(pitch_)),
                                        sinf(glm::radians(pitch_)),
                                        sinf(glm::radians(yaw_)) * cosf(glm::radians(pitch_))));
    right_ = glm::normalize(glm::cross(forward_, up_));
    viewDirty_ = true;
  }

  void Move(float forwardAxis, float rightAxis, float speed, float dt) {   
    pos_ += (forward_ * forwardAxis + right_ * rightAxis) * speed * dt;
    viewDirty_ = true;
  }

  void SetPos(const glm::vec3& pos) {
    pos_ = pos;
    viewDirty_ = true;
  }

  [[nodiscard]] const glm::vec3& GetPos() const {
    return pos_;
  }

  [[nodiscard]] const glm::vec3& GetForward() const {
    return forward_;
  }

  [[nodiscard]] const glm::vec3& GetRight() const {
    return right_;
  }

  [[nodiscard]] const glm::vec3& GetUp() const { return up_; }

  [[nodiscard]] float GetYaw() const { return yaw_; }
  [[nodiscard]] float GetPitch() const { return pitch_; }

  void SetRoll(float radians) {
    roll_ = radians;
    viewDirty_ = true;
  }

  void LookAt(const glm::vec3& eye, const glm::vec3& target) {
    pos_ = eye;
    forward_ = glm::normalize(target - eye);
    pitch_ = glm::degrees(asinf(forward_.y));
    yaw_ = glm::degrees(atan2f(forward_.x, forward_.z));
    viewDirty_ = true;
  }

  [[nodiscard]] const glm::mat4& GetView() const { 
    if (viewDirty_) UpdateView(); 
    return view_; 
  }

 private:
  void UpdateView() const;
 private:

  glm::vec3 pos_ = {0.0f, 1.0f, -3.0f};
  glm::vec3 up_ = {0.0f, 1.0f, 0.0f};
  float yaw_ = 0.0f;
  float pitch_ = 0.0f;
  float roll_ = 0.0f;
  glm::vec3 forward_ = {};
  glm::vec3 right_ = {};
  mutable glm::mat4 view_ = glm::mat4(1.0f);
  mutable bool viewDirty_ = true;
};

}  // namespace core


// ========== src\core\CameraShake.cpp ==========

#include "CameraShake.h"

#include <algorithm>
#include <cmath>

namespace core {

namespace {
constexpr float kTwoPi = 6.28318530718f;

float Noise(float t, float seed) {
  return 0.6f * sinf(t * 90.0f + seed) + 0.4f * sinf(t * 140.0f + seed * 1.7f);
}
}  // namespace

void CameraShake::Update(float dt, glm::vec3 horizontalVelocity, bool grounded) {
  dt = std::min(dt, 0.05f);

  float speed = glm::length(horizontalVelocity);
  airTime = grounded ? 0.0f : airTime + dt;
  bool walking = airTime < 0.1f && speed > 0.1f;

  if (walking) {
    bobPhase = fmodf(bobPhase + speed * dt * bobFrequency, kTwoPi);
  }
  float target = walking ? 1.0f : 0.0f;
  intensity += (target - intensity) * (1.0f - expf(-8.0f * dt));

  glm::vec3 acc = -kickOffset * springStiffness - kickVelocity * springDamping;
  kickVelocity += acc * dt;
  kickOffset += kickVelocity * dt;

  float rollAcc = -roll * springStiffness - rollVelocity * springDamping;
  rollVelocity += rollAcc * dt;
  roll += rollVelocity * dt;

  trauma = std::max(0.0f, trauma - traumaDecay * dt);
  shakeTime += dt;
}

void CameraShake::Impulse(glm::vec3 direction, float strength, float traumaAmount) {
  if (glm::length(direction) > 1e-4f) {
    direction = glm::normalize(direction);
  }
  kickVelocity += direction * strength;
  rollVelocity += -direction.x * strength * 0.3f;
  trauma = std::min(1.0f, trauma + traumaAmount);
}

glm::vec3 CameraShake::GetPositionOffset() const {
  float vertical = sinf(bobPhase * 2.0f) * bobAmplitudeY;
  float horizontal = cosf(bobPhase) * bobAmplitudeX;
  glm::vec3 bob = glm::vec3(horizontal, vertical, 0.0f) * intensity;

  float t2 = trauma * trauma;
  glm::vec3 shake(Noise(shakeTime, 0.0f), Noise(shakeTime, 17.0f), 0.0f);
  shake *= t2 * shakeAmplitude;

  return bob + kickOffset + shake;
}

float CameraShake::GetRoll() const {
  float t2 = trauma * trauma;
  return roll + Noise(shakeTime, 41.0f) * t2 * 0.04f;
}

}  // namespace core


// ========== src\core\CameraShake.h ==========

#pragma once

#include <glm/glm.hpp>
#include <cmath>
#include <algorithm>

namespace core {

class CameraShake {
 public:
  void Update(float dt, glm::vec3 horizontalVelocity, bool grounded);

  void AddTrauma(float amount, float maxTrauma) {
    if (trauma < maxTrauma) trauma = std::min(maxTrauma, trauma + amount);
  }

  void Impulse(glm::vec3 direction, float strength, float trauma = 0.0f);

  [[nodiscard]] glm::vec3 GetPositionOffset() const;
  [[nodiscard]] float GetRoll() const;

 private:

  float bobPhase = 0.0f;
  float intensity = 0.0f;
  float airTime = 0.0f;
  float bobFrequency = 1.25f;
  float bobAmplitudeY = 0.05f;
  float bobAmplitudeX = 0.03f;

  glm::vec3 kickOffset{0.0f};
  glm::vec3 kickVelocity{0.0f};
  float roll = 0.0f;
  float rollVelocity = 0.0f;
  float springStiffness = 150.0f;
  float springDamping = 12.0f;

  float trauma = 0.0f;
  float traumaDecay = 1.5f;
  float shakeTime = 0.0f;
  float shakeAmplitude = 0.08f;
};

}  // namespace core


// ========== src\core\InputAndroid.cpp ==========

#include "InputAndroid.h"

namespace core {

void InputAndroid::Reset() { inputState_.Reset(); }

void InputAndroid::Update(const AInputEvent* event) {
  if (AInputEvent_getType(event) != AINPUT_EVENT_TYPE_MOTION) {
    return;
  }

  int32_t action = AMotionEvent_getAction(event);
  int32_t actionType = action & AMOTION_EVENT_ACTION_MASK;
  int32_t index = (action & AMOTION_EVENT_ACTION_POINTER_INDEX_MASK) >>
                  AMOTION_EVENT_ACTION_POINTER_INDEX_SHIFT;

  switch (actionType) {
    case AMOTION_EVENT_ACTION_DOWN:
    case AMOTION_EVENT_ACTION_POINTER_DOWN:
      ProcessDown(event, index);
      break;
    case AMOTION_EVENT_ACTION_MOVE:
      ProcessMove(event);
      break;
    case AMOTION_EVENT_ACTION_UP:
    case AMOTION_EVENT_ACTION_POINTER_UP:
      ProcessUp(event, index);
      break;
    case AMOTION_EVENT_ACTION_CANCEL:
      ProcessCancel();
      break;
    default:
      break;
  }
}

void InputAndroid::ProcessDown(const AInputEvent* event, int32_t index) {
  auto& pointers = inputState_.pointers();
  int32_t id = AMotionEvent_getPointerId(event, index);
  float x = AMotionEvent_getX(event, index);
  float y = AMotionEvent_getY(event, index);

  Pointer t;
  t.startX = t.currentX = x;
  t.startY = t.currentY = y;
  t.pressure = AMotionEvent_getPressure(event, index);
  t.phase = Pointer::Phase::Began;

  pointers[id] = t;
}

void InputAndroid::ProcessMove(const AInputEvent* event) {
  size_t count = AMotionEvent_getPointerCount(event);

  auto& pointers = inputState_.pointers();

  for (size_t i = 0; i < count; ++i) {
    int32_t id = AMotionEvent_getPointerId(event, i);
    auto it = pointers.find(id);
    if (it == pointers.end()) {
      continue;
    }

    float x = AMotionEvent_getX(event, i);
    float y = AMotionEvent_getY(event, i);

    Pointer& t = it->second;
    t.deltaX = x - t.prevX;
    t.deltaY = y - t.prevY;
    t.currentX = x;
    t.currentY = y;
    t.pressure = AMotionEvent_getPressure(event, i);
    t.phase = Pointer::Phase::Moved;
  }
}

void InputAndroid::ProcessUp(const AInputEvent* event, int32_t index) {
  int32_t id = AMotionEvent_getPointerId(event, index);
  auto& pointers = inputState_.pointers();
  auto it = pointers.find(id);
  if (it == pointers.end()) {
    return;
  }

  float x = AMotionEvent_getX(event, index);
  float y = AMotionEvent_getY(event, index);

  Pointer& t = it->second;
  t.deltaX = x - t.prevX;
  t.deltaY = y - t.prevY;
  t.currentX = x;
  t.currentY = y;
  t.phase = Pointer::Phase::Ended;
}

void InputAndroid::ProcessCancel() {
  auto& pointers = inputState_.pointers();
  for (auto& [id, t] : pointers) {
    t.phase = Pointer::Phase::Cancelled;
  }
}

}  // namespace core


