// ========== src\game\voxel\Chunk.cpp ==========

#include "Chunk.h"

#include <cassert>
#include <cstdint>

namespace gm {

namespace {
uint32_t hashChunkPos(const glm::ivec3& pos) {
  uint32_t h = 2166136261u;
  auto mix = [&h](int32_t v) {
    h ^= static_cast<uint32_t>(v);
    h *= 16777619u;
  };
  mix(pos.x);
  mix(pos.y);
  mix(pos.z);
  return h;
}
}  // namespace

Chunk::Chunk(const glm::ivec3& pos)
    : voxels_(std::make_unique<Voxel[]>(kVolume)), pos_(pos) {
  constexpr int platformHeight = 4;
  constexpr uint32_t oreSpawnChance = 100;

  for (size_t i = 0; i < kVolume; ++i) {
    voxels_[i] = Voxel{0};
  }

  for (int y = 0; y < platformHeight; ++y) {
    for (int x = 0; x < kLength; ++x) {
      for (int z = 0; z < kLength; ++z) {
        size_t index = ArrayIndex({x, y, z});
        voxels_[index] = Voxel{1};
        nonEmptyCount_++;
      }
    }
  }

  uint32_t seed = hashChunkPos(pos_);

  bool spawnsOre = (seed % 100) < oreSpawnChance;
  spawnsOre = true;

  if (spawnsOre) {
    int oreX = static_cast<int>((seed / 100) % kLength);
    int oreZ = static_cast<int>((seed / 10000) % kLength);
    int oreY = platformHeight - 1;

    if (oreX >= 0 && oreX < kLength && oreY >= 0 && oreY < kLength && oreZ >= 0 && oreZ < kLength) {
      size_t oreIndex = ArrayIndex({oreX, oreY, oreZ});
      voxels_[oreIndex] = Voxel{2};
    }
  }
}

Voxel& Chunk::GetVoxel(const glm::ivec3& localPos) {
  assert(localPos.x >= 0 && localPos.x < kLength);
  assert(localPos.y >= 0 && localPos.y < kLength);
  assert(localPos.z >= 0 && localPos.z < kLength);

  return voxels_[ArrayIndex(localPos)];
}

const Voxel& Chunk::GetVoxel(const glm::ivec3& localPos) const {
  assert(localPos.x >= 0 && localPos.x < kLength);
  assert(localPos.y >= 0 && localPos.y < kLength);
  assert(localPos.z >= 0 && localPos.z < kLength);

  return voxels_[ArrayIndex(localPos)];
}

}  // namespace gm


// ========== src\game\voxel\Chunk.h ==========

#pragma once

#include <glm/glm.hpp>
#include <memory>

#include "Voxel.h"

namespace gm {

class Chunk {
 public:
  static constexpr size_t kLength = 32ull;
  static constexpr size_t kVolume = kLength * kLength * kLength;

  explicit Chunk(const glm::ivec3& pos);

  [[nodiscard]] Voxel& GetVoxel(const glm::ivec3& localPos);
  [[nodiscard]] const Voxel& GetVoxel(const glm::ivec3& localPos) const;

  void SetVoxel(const glm::ivec3& localPos, const Voxel& voxel) {
    if (localPos.x >= kLength || localPos.y >= kLength || localPos.z >= kLength) return;

    size_t voxelIndex = ArrayIndex(localPos);

    if (voxelIndex >= kVolume) return;

    bool wasEmpty = voxels_[voxelIndex].id == 0;
    bool isEmpty = voxel.id == 0;

    if (wasEmpty && !isEmpty) {
      ++nonEmptyCount_;
    } else if (!wasEmpty && isEmpty) {
      --nonEmptyCount_;
    }

    voxels_[voxelIndex] = voxel;
  }

  [[nodiscard]] glm::ivec3 pos() const { return pos_; }

  [[nodiscard]] bool IsEmpty() const { return nonEmptyCount_ == 0ll; }

 private:
  size_t ArrayIndex(const glm::ivec3& localPos) const {
    return static_cast<size_t>((localPos.x * kLength + localPos.y) * kLength + localPos.z);
  }
  std::unique_ptr<Voxel[]> voxels_;
  glm::ivec3 pos_;
  size_t nonEmptyCount_ = 0ll;
};

}  // namespace gm


// ========== src\game\voxel\ChunkManager.cpp ==========

#include "ChunkManager.h"

namespace gm {

ChunkManager::ChunkManager(uint32_t width, uint32_t height, uint32_t depth)
    : width_(width), height_(height), depth_(depth) {
  for (uint32_t x = 0; x < width_; ++x) {
    for (uint32_t y = 0; y < height_; ++y) {
      for (uint32_t z = 0; z < depth_; ++z) {
        glm::ivec3 chunkPos{static_cast<int>(x), static_cast<int>(y), static_cast<int>(z)};
        chunks_.emplace(chunkPos, std::make_unique<Chunk>(chunkPos));
        dirtyChunks_.emplace(chunkPos);
      }
    }
  }
}

}  // namespace gm


// ========== src\game\voxel\ChunkManager.h ==========

#pragma once

#include <cstddef>
#include <glm/glm.hpp>
#include <memory>
#include <optional>
#include <unordered_map>
#include <unordered_set>

#include "../../util/hashers.h"
#include "Chunk.h"

namespace gm {
using ChunksMap = std::unordered_map<glm::ivec3, std::unique_ptr<Chunk>, util::IVec3Hash>;
using DirtyChunkSet = std::unordered_set<glm::ivec3, util::IVec3Hash>;

class ChunkManager {
 public:
  ChunkManager(uint32_t width, uint32_t height, uint32_t depth);

  void MarkDirty(const glm::ivec3& worldPos) {
    glm::ivec3 chunkPos = toChunkPos(worldPos);
    glm::ivec3 localPos = toLocalPos(worldPos, chunkPos);
    markDirtyWithNeighbors(chunkPos, localPos);
  }

  bool isDirty(const glm::ivec3& chunkPos) const {
    return dirtyChunks_.find(chunkPos) != dirtyChunks_.end();
  }

  Chunk* getChunk(const glm::ivec3& chunkPos) {
    auto it = chunks_.find(chunkPos);
    return it != chunks_.end() ? it->second.get() : nullptr;
  }

  const Chunk* getChunk(const glm::ivec3& chunkPos) const {
    auto it = chunks_.find(chunkPos);
    return it != chunks_.end() ? it->second.get() : nullptr;
  }

  bool hasChunk(const glm::ivec3& chunkPos) const {
    return chunks_.find(chunkPos) != chunks_.end();
  }

  bool hasVoxel(const glm::ivec3& worldPos) const {
    glm::ivec3 chunkPos = toChunkPos(worldPos);
    return hasChunk(chunkPos);
  }

  std::optional<Voxel> getVoxel(const glm::ivec3& worldPos) const {
    glm::ivec3 chunkPos = toChunkPos(worldPos);
    const Chunk* chunk = getChunk(chunkPos);
    if (!chunk) {
      return std::nullopt;
    }
    return chunk->GetVoxel(toLocalPos(worldPos, chunkPos));
  }

  bool setVoxel(const glm::ivec3& worldPos, const Voxel& value) {
    glm::ivec3 chunkPos = toChunkPos(worldPos);
    Chunk* chunk = getChunk(chunkPos);
    if (!chunk) {
      return false;
    }
    glm::ivec3 localPos = toLocalPos(worldPos, chunkPos);
    chunk->SetVoxel(localPos, value);
    markDirtyWithNeighbors(chunkPos, localPos);
    return true;
  }

  DirtyChunkSet& getDirtyChunks() { return dirtyChunks_; }

  const DirtyChunkSet& getDirtyChunks() const { return dirtyChunks_; }

  std::optional<glm::ivec3> popDirtyChunk() {
    if (dirtyChunks_.empty()) {
      return std::nullopt;
    }
    auto it = dirtyChunks_.begin();
    glm::ivec3 chunkPos = *it;
    dirtyChunks_.erase(it);
    return chunkPos;
  }

  void clearDirty() { dirtyChunks_.clear(); }

  uint32_t width() const { return width_; }
  uint32_t height() const { return height_; }
  uint32_t depth() const { return depth_; }
  const ChunksMap& getChunks() const { return chunks_; }

 private:
  static glm::ivec3 toChunkPos(const glm::ivec3& worldPos) {
    constexpr int L = static_cast<int>(Chunk::kLength);
    return glm::ivec3{floorDiv(worldPos.x, L), floorDiv(worldPos.y, L), floorDiv(worldPos.z, L)};
  }

  static glm::ivec3 toLocalPos(const glm::ivec3& worldPos, const glm::ivec3& chunkPos) {
    constexpr int L = static_cast<int>(Chunk::kLength);
    return worldPos - chunkPos * L;
  }

  static int floorDiv(int a, int b) {
    int d = a / b;
    int r = a % b;
    return (r != 0 && ((r < 0) != (b < 0))) ? d - 1 : d;
  }

  void markDirtyWithNeighbors(const glm::ivec3& chunkPos, const glm::ivec3& localPos) {
    dirtyChunks_.insert(chunkPos);

    constexpr int last = Chunk::kLength - 1;

    if (localPos.x == 0) {
      dirtyChunks_.insert(chunkPos + glm::ivec3(-1, 0, 0));
    }
    if (localPos.x == last) {
      dirtyChunks_.insert(chunkPos + glm::ivec3(1, 0, 0));
    }
    if (localPos.y == 0) {
      dirtyChunks_.insert(chunkPos + glm::ivec3(0, -1, 0));
    }
    if (localPos.y == last) {
      dirtyChunks_.insert(chunkPos + glm::ivec3(0, 1, 0));
    }
    if (localPos.z == 0) {
      dirtyChunks_.insert(chunkPos + glm::ivec3(0, 0, -1));
    }
    if (localPos.z == last) {
      dirtyChunks_.insert(chunkPos + glm::ivec3(0, 0, 1));
    }
  }

  ChunksMap chunks_;
  DirtyChunkSet dirtyChunks_;
  uint32_t width_;
  uint32_t height_;
  uint32_t depth_;
};

}  // namespace gm


