#pragma once

#include <functional>
#include <unordered_map>

#include "../../../util/hashers.h"
#include "FontFace.h"
#include "FontStyle.h"
#include "Glyph.h"
#include "GlyphAtlas.h"

namespace gfx {
class Font {
 public:
  Font(const std::string& familyName, FontStyle style, FontFace&& fontFace,
       std::reference_wrapper<GlyphAtlas> glyphAtlas);

  [[nodiscard]] const Glyph& GetGlyph(char32_t c, uint32_t pixelSize);

  [[nodiscard]] const FontMetrics& GetMetrics(uint32_t pixelSize);

  [[nodiscard]] FontStyle GetStyle() const { return style_; }

  [[nodiscard]] const std::string& GetFamilyName() const { return familyName_; }

 private:
  struct GlyphKey {
    char32_t codepoint;
    uint32_t pixelSize;

    [[nodiscard]] bool operator==(const GlyphKey&) const = default;
  };

  struct GlyphKeyHash {
    [[nodiscard]] size_t operator()(const GlyphKey& key) const noexcept {
      size_t seed = 0;
      util::HashCombine(seed, key.codepoint);
      util::HashCombine(seed, key.pixelSize);
      return seed;
    }
  };

 private:
  std::string familyName_;
  FontStyle style_;
  FontFace face_;
  std::reference_wrapper<GlyphAtlas> glyphAtlas_;
  std::unordered_map<GlyphKey, Glyph, GlyphKeyHash> glyphs_;
  std::unordered_map<uint32_t, FontMetrics> metrics_;
};
}  // namespace gfx


// ========== src\gfx\common\font\FontFace.cpp ==========

#include "FontFace.h"

#include <cstring>
#include <stdexcept>
#include <string>
#include <cassert>

namespace gfx {
FontFace::FontFace(const FreeTypeLibrary& lib, std::vector<std::byte>&& bytes)
    : bytes_(std::move(bytes)), face_(CreateFace(lib)) {
  assert(face_);
}

FontFace::FtFacePtr FontFace::CreateFace(const FreeTypeLibrary& lib) {
  FT_Face face = nullptr;
  if (FT_Error e =
          FT_New_Memory_Face(lib.GetHandle(), reinterpret_cast<const FT_Byte*>(bytes_.data()),
                             static_cast<FT_Long>(bytes_.size()), 0, &face)) {
    throw std::runtime_error("Failed to create FT_Face. Error code: " + std::to_string(e));
  }
  return FtFacePtr(face);
}

void FontFace::SetSize(uint32_t w, uint32_t h) {
  if (!h) h = w;
  if (!w) w = h;
  if (w == currentWidth_ && h == currentHeight_) return;
  if (FT_Error e = FT_Set_Pixel_Sizes(face_.get(), w, h)) {
    throw std::runtime_error("Failed to set pixel size. Error code: " + std::to_string(e));
  }
  currentWidth_ = w;
  currentHeight_ = h;
}

FontMetrics FontFace::GetMetrics() const {
  const FT_Size_Metrics& m = face_->size->metrics;

  FontMetrics result;
  result.ascent = static_cast<float>(m.ascender) / 64.0f;
  result.descent = static_cast<float>(-m.descender) / 64.0f;
  result.lineHeight = static_cast<float>(m.height) / 64.0f;
  return result;
}

RasterizedGlyph FontFace::Rasterize(char32_t c, uint32_t w, uint32_t h) {
  SetSize(w, h);

  FT_Face face = face_.get();

  FT_UInt index = FT_Get_Char_Index(face, static_cast<FT_ULong>(c));
   
  if (FT_Error e = FT_Load_Glyph(face, index, FT_LOAD_DEFAULT)) {
    throw std::runtime_error("Failed to load glyph U+" + std::to_string(static_cast<uint32_t>(c)) +
                             ". Error code: " + std::to_string(e));
  }

  if (FT_Error e = FT_Render_Glyph(face->glyph, FT_RENDER_MODE_NORMAL)) {
    throw std::runtime_error("Failed to render glyph U+" +
                             std::to_string(static_cast<uint32_t>(c)) +
                             ". Error code: " + std::to_string(e));
  }

  const FT_GlyphSlot slot = face->glyph;
  const FT_Bitmap& bmp = slot->bitmap;

  RasterizedGlyph result = {};

  result.metrics.size.x = static_cast<int32_t>(bmp.width);
  result.metrics.size.y = static_cast<int32_t>(bmp.rows);
  result.metrics.bearing.x = slot->bitmap_left;
  result.metrics.bearing.y = slot->bitmap_top;
  result.metrics.advance = static_cast<float>(slot->advance.x) / 64.0f;

  result.pixels.resize(static_cast<size_t>(bmp.width) * bmp.rows);

  for (uint32_t row = 0; row < bmp.rows; ++row) {
    std::memcpy(result.pixels.data() + static_cast<size_t>(row) * bmp.width,
                bmp.buffer + static_cast<ptrdiff_t>(row) * bmp.pitch, bmp.width);
  }

  return result;
}
}  // namespace gfx


