// ========== src\gfx\common\mesh\Model.cpp ==========

#include "Model.h"

#include <cassert>

namespace gfx {

Model::Model(ModelId id, const vkcore::Device& device, std::vector<Submesh>&& submeshes)
    : id_(id), device_(&device), submeshes_(std::move(submeshes)) {}

void Model::Draw(VkCommandBuffer cmd, const vkcore::PipelineLayout& pipelineLayout,
                 VkBuffer instanceBuffer, VkDeviceSize instanceOffset,
                 uint32_t instanceCount) const {
  const Material* lastMaterial = nullptr;

  for (const auto& sub : submeshes_) {
    if (sub.material != lastMaterial && sub.material) {
      VkDescriptorSet matSet = sub.material->descriptorSet.GetHandle();
      device_->GetDispatchTable().vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS,
                                                       pipelineLayout.GetHandle(), kMaterialBindingSet,
                                                       1, &matSet, 0, nullptr);
      lastMaterial = sub.material;
    }

    VkBuffer vertexBuffers[] = {sub.mesh.vertexBuffer().GetHandle(), instanceBuffer};
    VkDeviceSize offsets[] = {sub.mesh.vertexBuffer().GetOffset(), instanceOffset};
    device_->GetDispatchTable().vkCmdBindVertexBuffers(cmd, 0, 2, vertexBuffers, offsets);
    sub.mesh.indexBuffer()->BindIndex(cmd);
    device_->GetDispatchTable().vkCmdDrawIndexed(cmd, sub.mesh.indexCount(), instanceCount, 0, 0, 0);
  }
}

}  // namespace gfx


// ========== src\gfx\common\mesh\Model.h ==========

#pragma once

#include <glm/glm.hpp>
#include <limits>
#include <vector>

#include "../../../vkcore/pipeline/PipelineLayout.h"
#include "../texture/MaterialManager.h"
#include "Mesh.h"

namespace gfx {

using ModelId = uint32_t;
static constexpr ModelId kInvalidModelId = std::numeric_limits<ModelId>::max();

class Model {
 public:
  struct Vertex {
    glm::vec3 pos;
    glm::vec2 uv;
    glm::vec3 normal;

    [[nodiscard]] bool operator==(const Vertex& other) const {
      return pos == other.pos && uv == other.uv && normal == other.normal;
    }
  };

  struct Submesh {
    Mesh mesh;
    const Material* material;
  };

  Model(ModelId id, const vkcore::Device& device, std::vector<Submesh>&& submeshes);

  void Draw(VkCommandBuffer cmd, const vkcore::PipelineLayout& pipelineLayout,
            VkBuffer instanceBuffer, VkDeviceSize instanceOffset, uint32_t instanceCount) const;

  ModelId id() const { return id_; }

 private:
  static constexpr uint32_t kMaterialBindingSet = 1u;
  ModelId id_;
  const vkcore::Device* device_;
  std::vector<Submesh> submeshes_;
};

}  // namespace gfx


// ========== src\gfx\common\mesh\ModelCache.cpp ==========

#include "ModelCache.h"

#include "ModelLoader.h"

namespace gfx {

ModelCache::ModelCache(const vkcore::Device& device, vkcore::TransferContext& transferCtxt,
                       vkcore::BufferAllocator& bufferAllocator,
                       TextureManager& textureManager, uint32_t framesCount)
    : device_(&device),
      transferCtxt_(&transferCtxt),
      bufferAllocator_(&bufferAllocator),
      framesCount_(framesCount),
      materialCache_(device, textureManager) {}

ModelId ModelCache::Require(std::string_view path) {
  auto it = pathToId_.find(path);

  if (it != pathToId_.end()) return it->second;

  auto model = ModelLoader::Load(static_cast<ModelId>(models_.size()), *device_, *transferCtxt_,
                                 *bufferAllocator_, materialCache_, path);

  if (!model) return kInvalidModelId;

  const ModelId id = static_cast<ModelId>(models_.size());

  models_.emplace_back(std::move(*model));
  paths_.emplace_back(path);
  pathToId_.emplace(paths_.back(), id);

  return id;
}

Model* ModelCache::Get(ModelId id) {
  if (id >= models_.size()) return nullptr;
  return &models_[id];
}

const Model* ModelCache::Get(ModelId id) const {
  if (id >= models_.size()) return nullptr;

  return &models_[id];
}

}  // namespace gfx


