// ========== src\gfx\render\billboard\BillboardBatch.cpp ==========

#include "BillboardBatch.h"

#include <algorithm>

namespace gfx {

BillboardBatch::BillboardBatch(const vkcore::Device& device,
                               vkcore::BufferAllocator& bufferAllocator,
                               const vkcore::DescriptorSet& atlasDescriptorSet,
                               const vkcore::PipelineLayout& pipelineLayout, uint32_t framesCount,
                               SortingMode sortingMode)
    : device_(&device),
      descriptorSet_(&atlasDescriptorSet),
      pipelineLayout_(&pipelineLayout),
      sortingMode_(sortingMode) {
  frames_.reserve(framesCount);

  if (sortingMode_ == SortingMode::BackToFront) {
    instances_.reserve(kMaxbillboards);
    sortBuffer_.reserve(kMaxbillboards);
  }

  for (uint32_t i = 0; i < framesCount; ++i) {
    auto buffer = bufferAllocator.Allocate(kBufferSize, kBufferUsage, kMemoryProperties);

    auto mapped = std::span<BillboardInstance>(reinterpret_cast<BillboardInstance*>(buffer.Map()),
                                               kMaxbillboards);

    frames_.emplace_back(mapped, std::move(buffer));
  }
}

void BillboardBatch::Submit(const BillboardInstance& billboard, uint32_t currentFrame) {
  if (billboardCount_ >= kMaxbillboards) {
    return;
  }

  if (sortingMode_ == SortingMode::None) {
    frames_[currentFrame].mapped[billboardCount_] = billboard;
  } else {
    instances_.push_back(billboard);
  }

  ++billboardCount_;
}

void BillboardBatch::Render(VkCommandBuffer cmd, const glm::vec3& cameraPosition,
                            uint32_t currentFrame) {
  if (billboardCount_ == 0) {
    return;
  }

  FrameData& frame = frames_[currentFrame];

  if (sortingMode_ == SortingMode::BackToFront) {
    sortBuffer_.clear();

    for (uint32_t i = 0; i < billboardCount_; ++i) {
      sortBuffer_.push_back({
          i,
          glm::length2(instances_[i].pos - cameraPosition),
      });
    }

    std::sort(sortBuffer_.begin(), sortBuffer_.end(),
              [](const BillboardSortEntry& a, const BillboardSortEntry& b) {
                return a.distance > b.distance;
              });

    for (uint32_t i = 0; i < billboardCount_; ++i) {
      frame.mapped[i] = instances_[sortBuffer_[i].index];
    }
  }

  const auto& dt = device_->GetDispatchTable();

  VkDescriptorSet sets[] = {
      descriptorSet_->GetHandle(),
  };

  dt.vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, pipelineLayout_->GetHandle(),
                             kAtlasSetIndex, 1, sets, 0, nullptr);

  VkBuffer buffers[] = {frame.instanceBuffer.GetHandle()};
  VkDeviceSize offsets[] = {frame.instanceBuffer.GetOffset()};

  dt.vkCmdBindVertexBuffers(cmd, 0, 1, buffers, offsets);

  dt.vkCmdDraw(cmd, 4, billboardCount_, 0, 0);

  if (sortingMode_ != SortingMode::None) {
    instances_.clear();
    sortBuffer_.clear();
  }
  billboardCount_ = 0;
}

}  // namespace gfx


// ========== src\gfx\render\billboard\BillboardBatch.h ==========

#pragma once

#include <span>
#include <vector>

#include "../../common/texture/Atlas.h"
#include "BillboardInstance.h"
#include "BillboardPipelines.h"
#include "glm/gtx/norm.hpp"

namespace gfx {

class BillboardBatch {
 public:
  enum class SortingMode {
    None,
    BackToFront,
  };

  BillboardBatch(const vkcore::Device& device, vkcore::BufferAllocator& bufferAllocator,
                 const vkcore::DescriptorSet& atlasDescriptorSet,
                 const vkcore::PipelineLayout& pipelineLayout, uint32_t framesCount,
                 SortingMode sortingMode = SortingMode::None);

  void BeginFrame(uint32_t currentFrame);

  void Submit(const BillboardInstance& billboard, uint32_t currentFrame);

  void Render(VkCommandBuffer cmd, const glm::vec3& cameraPos, uint32_t currentFrame);

  [[nodiscard]] bool IsEmpty() const { return billboardCount_ == 0; }

 private:
  static constexpr VkDeviceSize kBufferSize = 6 * 1024 * 1024ull;
  static constexpr size_t kMaxbillboards = kBufferSize / sizeof(BillboardInstance);

  static constexpr VkBufferUsageFlags kBufferUsage = VK_BUFFER_USAGE_VERTEX_BUFFER_BIT;

  static constexpr VkMemoryPropertyFlags kMemoryProperties =
      VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT;

  static constexpr uint32_t kAtlasSetIndex = 1u;

  struct BillboardSortEntry {
    uint32_t index;
    float distance;
  };

  struct FrameData {
    std::span<BillboardInstance> mapped;
    vkcore::BufferSlice instanceBuffer;

    FrameData(std::span<BillboardInstance> mapped, vkcore::BufferSlice&& instanceBuffer)
        : mapped(mapped), instanceBuffer(std::move(instanceBuffer)) {}
  };

 private:
  const vkcore::Device* device_;
  const vkcore::PipelineLayout* pipelineLayout_;
  const vkcore::DescriptorSet* descriptorSet_;

  SortingMode sortingMode_;

  std::vector<FrameData> frames_;

  uint32_t billboardCount_ = 0;

  std::vector<BillboardInstance> instances_;
  std::vector<BillboardSortEntry> sortBuffer_;
};

}  // namespace gfx


