// ========== src\gfx\render\chunk\ChunkMeshBuilder.cpp ==========

#include "ChunkMeshBuilder.h"

namespace gfx {

namespace {

static constexpr glm::ivec3 kFaceNormals[6u] = {
    {0, 0, -1},  // Z-
    {0, 0, 1},   // Z+
    {-1, 0, 0},  // X-
    {1, 0, 0},   // X+
    {0, -1, 0},  // Y-
    {0, 1, 0},   // Y+
};

static constexpr glm::ivec3 kFaceRight[6u] = {
    {1, 0, 0},  // 0: -Z
    {1, 0, 0},  // 1: +Z
    {0, 0, 1},  // 2: -X
    {0, 0, 1},  // 3: +X
    {1, 0, 0},  // 4: -Y
    {1, 0, 0},  // 5: +Y
};

static constexpr glm::ivec3 kFaceUp[6u] = {
    {0, 1, 0},  // 0: -Z
    {0, 1, 0},  // 1: +Z
    {0, 1, 0},  // 2: -X
    {0, 1, 0},  // 3: +X
    {0, 0, 1},  // 4: -Y
    {0, 0, 1},  // 5: +Y
};

#include "facePositions.inl"

struct CornerSign {
  int8_t right;
  int8_t up;
};

static std::array<CornerSign, 24> BuildCornerSigns() {
  std::array<CornerSign, 24> signs{};

  for (uint32_t face = 0; face < 6u; ++face) {
    for (uint32_t corner = 0; corner < 4u; ++corner) {
      uint32_t idx = face * 4u + corner;

      const glm::vec3& p = kFaceVertices[idx].pos;

      float rightDot = glm::dot(p, glm::vec3(kFaceRight[face]));
      float upDot = glm::dot(p, glm::vec3(kFaceUp[face]));

      signs[idx].right = rightDot > 0.0f ? 1 : -1;
      signs[idx].up = upDot > 0.0f ? 1 : -1;
    }
  }

  return signs;
}

static const std::array<CornerSign, 24> kCornerSigns = BuildCornerSigns();

static constexpr int32_t kChunkCubeLen = 3;

static constexpr size_t kChunkCubeVolume =
    static_cast<size_t>(kChunkCubeLen) * kChunkCubeLen * kChunkCubeLen;

static uint32_t ChunkCubeIndex(glm::ivec3 offset) {
  offset += glm::ivec3(1);

  return static_cast<uint32_t>((offset.x * kChunkCubeLen + offset.y) * kChunkCubeLen + offset.z);
}

static std::array<const gm::Chunk*, kChunkCubeVolume> CollectNeighbors(
    const gm::ChunksMap& chunksMap, const glm::ivec3& pos) {
  std::array<const gm::Chunk*, kChunkCubeVolume> neighbors{};

  for (int32_t dx = -1; dx <= 1; ++dx) {
    for (int32_t dy = -1; dy <= 1; ++dy) {
      for (int32_t dz = -1; dz <= 1; ++dz) {
        glm::ivec3 offset(dx, dy, dz);

        const auto& it = chunksMap.find(pos + offset);

        neighbors[ChunkCubeIndex(offset)] = (it == chunksMap.end()) ? nullptr : it->second.get();
      }
    }
  }

  return neighbors;
}

static const gm::Chunk* ResolveChunk(
    const gm::Chunk& self, const std::array<const gm::Chunk*, kChunkCubeVolume>& neighbors,
    glm::ivec3& localPos) {
  glm::ivec3 chunkOffset(0);

  chunkOffset.x =
      localPos.x < 0 ? -1 : (localPos.x >= static_cast<int32_t>(gm::Chunk::kLength) ? 1 : 0);

  chunkOffset.y =
      localPos.y < 0 ? -1 : (localPos.y >= static_cast<int32_t>(gm::Chunk::kLength) ? 1 : 0);

  chunkOffset.z =
      localPos.z < 0 ? -1 : (localPos.z >= static_cast<int32_t>(gm::Chunk::kLength) ? 1 : 0);

  if (chunkOffset == glm::ivec3(0)) {
    return &self;
  }

  int32_t len = static_cast<int32_t>(gm::Chunk::kLength);

  localPos.x = (localPos.x % len + len) % len;
  localPos.y = (localPos.y % len + len) % len;
  localPos.z = (localPos.z % len + len) % len;

  return neighbors[ChunkCubeIndex(chunkOffset)];
}

static bool IsLightBlocking(const gm::Chunk& self,
                            const std::array<const gm::Chunk*, kChunkCubeVolume>& neighbors,
                            const gm::BlockManager& blockManager, glm::ivec3 worldPos) {
  const glm::ivec3 chunkOrigin = self.pos() * static_cast<int32_t>(gm::Chunk::kLength);

  glm::ivec3 localPos = worldPos - chunkOrigin;

  const gm::Chunk* target = ResolveChunk(self, neighbors, localPos);

  if (!target) {
    return true;
  }

  const gm::Voxel& voxel = target->GetVoxel(localPos);

  if (!voxel.id) {
    return false;
  }

  const gm::Block* block = blockManager.GetBlock(voxel.id);

  if (!block) {
    return true;
  }

  return !block->isPassingLight();
}

glm::vec4 LightSample(const gm::Chunk& self,
                      const std::array<const gm::Chunk*, kChunkCubeVolume>& neighbors,
                      const gm::BlockManager& blockManager, const gm::Lighting& lighting,
                      glm::ivec3 worldPos, uint32_t face, uint32_t corner) {
  const CornerSign& sign = kCornerSigns[face * 4u + corner];

  const glm::ivec3 facePos = worldPos + kFaceNormals[face];

  const glm::ivec3 rightOffset = kFaceRight[face] * static_cast<int32_t>(sign.right);

  const glm::ivec3 upOffset = kFaceUp[face] * static_cast<int32_t>(sign.up);

  const glm::ivec3 rightPos = facePos + rightOffset;
  const glm::ivec3 upPos = facePos + upOffset;
  const glm::ivec3 cornerPos = rightPos + upOffset;

  const glm::vec4 faceLight = lighting.GetColor(facePos);
  const glm::vec4 upLight = lighting.GetColor(upPos);
  const glm::vec4 rightLight = lighting.GetColor(rightPos);

  const bool rightBlocked = IsLightBlocking(self, neighbors, blockManager, rightPos);

  const bool upBlocked = IsLightBlocking(self, neighbors, blockManager, upPos);

  if (rightBlocked && upBlocked) {
    return (faceLight + upLight + rightLight) / 3.0f;
  }

  const glm::vec4 cornerLight = lighting.GetColor(cornerPos);

  return (faceLight + upLight + rightLight + cornerLight) * 0.25f;
}

bool IsBlocked(BlockRenderData& renderData, const gm::Chunk& self,
               const std::array<const gm::Chunk*, kChunkCubeVolume>& neighbors,
               glm::ivec3 neighborLocalPos, uint32_t sourceVoxelId) {
  const gm::Chunk* target = ResolveChunk(self, neighbors, neighborLocalPos);

  if (!target) {
    return true;
  }

  uint32_t neighborId = target->GetVoxel(neighborLocalPos).id;

  return renderData.GetRenderGroupId(neighborId) == renderData.GetRenderGroupId(sourceVoxelId);
}

}  // namespace

ChunkMeshBuilder::ChunkMeshBuilder(const vkcore::Device& device, const gm::Lighting& lighting,
                                   const gm::BlockManager& blockManager,
                                   BlockRenderData& blockRenderData, uint32_t framesCount)
    : device_(&device),
      blockManager_(&blockManager),
      lighting_(&lighting),
      blockRenderData_(&blockRenderData),
      memoryAllocator_(device),
      bufferAllocator_(device, memoryAllocator_),
      framesCount_(framesCount) {
  stagingInfos_.reserve(framesCount);

  for (size_t i = 0; i < static_cast<uint32_t>(framesCount); ++i) {
    stagingInfos_.emplace_back(bufferAllocator_);
  }
}

bool ChunkMeshBuilder::AddFace(StagingInfo& staging, uint32_t face, const glm::vec3& worldOffset,
                               uint32_t surfaceId, const std::array<glm::vec4, 4>& cornerColors,
                               RenderLayer renderLayer) {
  MeshStream& stream = staging.GetLayer(renderLayer);

  if (!stream.CanFit(1)) {
    return false;
  }

  std::array<Vertex, 4> vertices;

  for (uint32_t corner = 0; corner < 4u; ++corner) {
    vertices[corner] = kFaceVertices[face * 4u + corner];

    vertices[corner].pos += worldOffset;
    vertices[corner].color = cornerColors[corner];
    vertices[corner].blockSurfaceId = surfaceId;
  }

  std::array<uint32_t, 6> localIndices;

  for (uint32_t i = 0; i < 6u; ++i) {
    localIndices[i] = kFaceIndices[face * 6u + i];
  }

  const uint32_t baseVertex = stream.PushQuad(vertices, localIndices);

  if (renderLayer == RenderLayer::Translucent) {
    std::array<uint32_t, 6> globalIndices;

    for (size_t i = 0; i < 6u; ++i) {
      globalIndices[i] = baseVertex + localIndices[i];
    }

    staging.AddTranslucentQuad(worldOffset, globalIndices);
  }

  return true;
}

std::optional<Mesh> ChunkMeshBuilder::MakeMeshLayer(VkCommandBuffer cmd, const StagingInfo& staging,
                                                    RenderLayer renderLayer) {
  const MeshStream& stream = staging.GetLayer(renderLayer);

  if (stream.empty()) {
    return std::nullopt;
  }

  vkcore::BufferSlice vertexBuffer = bufferAllocator_.Allocate(
      stream.VertexBytes(), VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_VERTEX_BUFFER_BIT,
      VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);

  vkcore::BufferSlice indexBuffer = bufferAllocator_.Allocate(
      stream.IndexBytes(), VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_INDEX_BUFFER_BIT,
      VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);

  VkBufferCopy vertexRegion{};
  vertexRegion.srcOffset = stream.VertexSrcOffset();
  vertexRegion.dstOffset = vertexBuffer.GetOffset();
  vertexRegion.size = stream.VertexBytes();

  VkBufferMemoryBarrier barrier = {VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER};
  barrier.buffer = vertexBuffer.GetHandle();
  barrier.offset = vertexBuffer.GetOffset();
  barrier.size = vertexBuffer.GetSize();
  barrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
  barrier.dstAccessMask = VK_ACCESS_VERTEX_ATTRIBUTE_READ_BIT;
  barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
  barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;

  barriers_.emplace_back(barrier);

  barrier.buffer = indexBuffer.GetHandle();
  barrier.offset = indexBuffer.GetOffset();
  barrier.size = indexBuffer.GetSize();
  barrier.dstAccessMask = VK_ACCESS_INDEX_READ_BIT;

  barriers_.emplace_back(barrier);

  device_->GetDispatchTable().vkCmdCopyBuffer(cmd, staging.GetBufferHandle(), vertexBuffer.GetHandle(), 1,
                                           &vertexRegion);

  VkBufferCopy indexRegion{};
  indexRegion.srcOffset = stream.IndexSrcOffset();
  indexRegion.dstOffset = indexBuffer.GetOffset();
  indexRegion.size = stream.IndexBytes();

  device_->GetDispatchTable().vkCmdCopyBuffer(cmd, staging.GetBufferHandle(), indexBuffer.GetHandle(), 1,
                                           &indexRegion);

  return Mesh(*device_, std::move(vertexBuffer), stream.vertexCount(), std::move(indexBuffer),
              stream.indexCount(), VK_INDEX_TYPE_UINT32);
}

std::optional<TranslucentMesh> ChunkMeshBuilder::MakeTranslucentMesh(VkCommandBuffer cmd,
                                                                     StagingInfo& staging) {
  MeshStream& stream = staging.GetLayer(RenderLayer::Translucent);

  if (stream.empty()) {
    return std::nullopt;
  }

  vkcore::BufferSlice vertexBuffer = bufferAllocator_.Allocate(
      stream.VertexBytes(), VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_VERTEX_BUFFER_BIT,
      VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);

  VkBufferCopy vertexRegion{};
  vertexRegion.srcOffset = stream.VertexSrcOffset();
  vertexRegion.dstOffset = vertexBuffer.GetOffset();
  vertexRegion.size = stream.VertexBytes();

  device_->GetDispatchTable().vkCmdCopyBuffer(cmd, staging.GetBufferHandle(), vertexBuffer.GetHandle(), 1,
                                           &vertexRegion);
  VkBufferMemoryBarrier barrier = {VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER};
  barrier.buffer = vertexBuffer.GetHandle();
  barrier.offset = vertexBuffer.GetOffset();
  barrier.size = vertexBuffer.GetSize();
  barrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
  barrier.dstAccessMask = VK_ACCESS_VERTEX_ATTRIBUTE_READ_BIT;
  barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
  barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;

  barriers_.emplace_back(barrier);

  Mesh mesh(*device_, std::move(vertexBuffer), stream.vertexCount());

  return TranslucentMesh(*device_, std::move(mesh), bufferAllocator_, framesCount_,
                         staging.GetTranslucentQuads());
}

bool ChunkMeshBuilder::BuildChunk(VkCommandBuffer cmd, StagingInfo& staging,
                                  const gm::ChunksMap& chunksMap, const gm::Chunk& chunk) {
  using clock = std::chrono::steady_clock;

  const auto t0 = clock::now();

  auto neighbors = CollectNeighbors(chunksMap, chunk.pos());

  for (uint32_t face = 0; face < 6; face++) {
    for (uint32_t x = 0; x < gm::Chunk::kLength; x++) {
      for (uint32_t y = 0; y < gm::Chunk::kLength; y++) {
        for (uint32_t z = 0; z < gm::Chunk::kLength; z++) {
          glm::ivec3 localPos(x, y, z);

          const gm::Voxel& v = chunk.GetVoxel(localPos);

          if (!v.id) {
            continue;
          }

          const gm::Block* block = blockManager_->GetBlock(v.id);

          if (IsBlocked(*blockRenderData_, chunk, neighbors, localPos + kFaceNormals[face], v.id)) {
            continue;
          }

          RenderLayer renderLayer = ToRenderLayer(block->renderLayer());

          if (renderLayer >= RenderLayer::Count) {
            continue;
          }

          uint32_t blockSurfaceId =
              block ? blockRenderData_->GetSurfaceId(v.id, static_cast<gm::Block::Face>(face)) : 0;

          std::array<glm::vec4, 4> cornerColors;

          if (!block || block->isIgnoreLighting()) {
            cornerColors.fill(glm::vec4(1.0f));
          } else {
            const glm::ivec3 worldPos =
                localPos + chunk.pos() * static_cast<int>(gm::Chunk::kLength);

            for (uint32_t corner = 0; corner < 4u; ++corner) {
              cornerColors[corner] =
                  LightSample(chunk, neighbors, *blockManager_, *lighting_, worldPos, face, corner);
            }
          }

          glm::vec3 worldOffset = glm::vec3(localPos) + glm::vec3(0.5f) +
                                  glm::vec3(chunk.pos()) * static_cast<float>(gm::Chunk::kLength);

          if (!AddFace(staging, face, worldOffset, blockSurfaceId, cornerColors, renderLayer)) {
            const auto t1 = clock::now();

            const double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();

            printf("BuildChunk (failed): %.3f ms\n", ms);

            return false;
          }
        }
      }
    }
  }

  const auto t1 = clock::now();

  const double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();

  printf("BuildChunk: %.3f ms\n", ms);

  return true;
}

void ChunkMeshBuilder::BuildMeshes(VkCommandBuffer cmd, uint32_t currentFrame,
                                   gm::DirtyChunkSet& dirtyChunks, const gm::ChunksMap& chunksMap,
                                   ChunkMeshes& meshes) {
  StagingInfo& staging = stagingInfos_[currentFrame];

  staging.Reset();

  barriers_.clear();

  auto it = dirtyChunks.begin();

  while (it != dirtyChunks.end()) {
    const glm::ivec3& pos = *it;

    auto chunkIt = chunksMap.find(pos);

    if (chunkIt == chunksMap.end() || chunkIt->second->IsEmpty()) {
      it = dirtyChunks.erase(it);
      continue;
    }

    const gm::Chunk& chunk = *chunkIt->second;

    if (!BuildChunk(cmd, staging, chunksMap, chunk)) {
      break;
    }

    if (auto mesh = MakeMeshLayer(cmd, staging, RenderLayer::Solid)) {
      meshes.solid.emplace(pos, std::move(*mesh));
    }

    if (auto mesh = MakeMeshLayer(cmd, staging, RenderLayer::Cutout)) {
      meshes.cutout.emplace(pos, std::move(*mesh));
    }

    if (auto mesh = MakeTranslucentMesh(cmd, staging)) {
      meshes.translucent.emplace(pos, std::move(*mesh));
    }

    staging.CommitChunk();

    it = dirtyChunks.erase(it);
  }

  device_->GetDispatchTable().vkCmdPipelineBarrier(
      cmd, VK_PIPELINE_STAGE_TRANSFER_BIT, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, 0, 0, nullptr,
      static_cast<uint32_t>(barriers_.size()), barriers_.data(), 0, nullptr);
}

}  // namespace gfx


// ========== src\gfx\render\chunk\ChunkMeshBuilder.h ==========

#pragma once

#include <stdint.h>

#include <array>
#include <cassert>
#include <vector>

#include "../block/BlockRenderData.h"
#include "../RenderLayers.h"
#include "ChunkMeshes.h"
#include "../../../game/lighting/Lighting.h"

namespace gfx {
class ChunkMeshBuilder {
 public:
  struct Vertex {
    glm::vec3 pos;
    glm::vec4 color;
    uint8_t faceIndex;
    uint8_t cornerIndex;
    uint32_t blockSurfaceId;
  };

  ChunkMeshBuilder(const vkcore::Device& device, const gm::Lighting& lighting, const gm::BlockManager& blockManager,
                   BlockRenderData& blockRenderData, uint32_t framesCount);

  void BuildMeshes(VkCommandBuffer cmd, uint32_t currentFrame, gm::DirtyChunkSet& dirtyChunks,
                   const gm::ChunksMap& chunksMap, ChunkMeshes& meshes);

  static constexpr size_t kBakedLength = gm::Chunk::kLength + 2ull;
  static constexpr size_t kBakedVolume = kBakedLength * kBakedLength * kBakedLength;

 private:
  class MeshStream {
   public:
    static constexpr uint32_t kVerticesPerQuad = 4u;
    static constexpr uint32_t kIndicesPerQuad = 6u;


    MeshStream() = default;

    MeshStream(uint8_t* mappedBase, VkDeviceSize baseOffset, VkDeviceSize regionBytes) {
      const VkDeviceSize vertexBytes = VertexBytesOf(regionBytes);
      const VkDeviceSize indexBytes = regionBytes - vertexBytes;

      vertexStagingOffset_ = baseOffset;
      indexStagingOffset_ = baseOffset + vertexBytes;

      vertexData_ = reinterpret_cast<Vertex*>(mappedBase + vertexStagingOffset_);
      indexData_ = reinterpret_cast<uint32_t*>(mappedBase + indexStagingOffset_);

      vertexCapacity_ = static_cast<uint32_t>(vertexBytes / sizeof(Vertex));
      indexCapacity_ = static_cast<uint32_t>(indexBytes / sizeof(uint32_t));
    }

    bool CanFit(uint32_t quadCount) const {
      return vertexCount_ + quadCount * kVerticesPerQuad <= vertexCapacity_ &&
             indexCount_ + quadCount * kIndicesPerQuad <= indexCapacity_;
    }

    bool empty() const { return vertexCount_ == 0; }

    uint32_t PushQuad(const std::array<Vertex, 4>& vertices,
                      const std::array<uint32_t, 6>& localIndices) {
      assert(CanFit(1));

      const uint32_t baseVertex = vertexCount_;

      for (size_t i = 0; i < kVerticesPerQuad; ++i) {
        vertexData_[vertexOffset_ + vertexCount_++] = vertices[i];
      }
      for (size_t i = 0; i < kIndicesPerQuad; ++i) {
        indexData_[indexOffset_ + indexCount_++] = baseVertex + localIndices[i];
      }

      return baseVertex;
    }

    void CommitChunk() {
      vertexOffset_ += vertexCount_;
      indexOffset_ += indexCount_;
      vertexCount_ = 0;
      indexCount_ = 0;
    }

    void Reset() {
      vertexOffset_ = 0;
      indexOffset_ = 0;
      vertexCount_ = 0;
      indexCount_ = 0;
    }

    uint32_t vertexCount() const { return vertexCount_; }
    uint32_t indexCount() const { return indexCount_; }

    VkDeviceSize VertexSrcOffset() const {
      return vertexStagingOffset_ + static_cast<VkDeviceSize>(vertexOffset_) * sizeof(Vertex);
    }
    VkDeviceSize VertexBytes() const {
      return static_cast<VkDeviceSize>(vertexCount_) * sizeof(Vertex);
    }
    VkDeviceSize IndexSrcOffset() const {
      return indexStagingOffset_ + static_cast<VkDeviceSize>(indexOffset_) * sizeof(uint32_t);
    }
    VkDeviceSize IndexBytes() const {
      return static_cast<VkDeviceSize>(indexCount_) * sizeof(uint32_t);
    }
    const uint32_t* IndexData() const { return indexData_ + indexOffset_; }

   private:
    static constexpr VkDeviceSize kQuadVertexBytes = kVerticesPerQuad * sizeof(Vertex);
    static constexpr VkDeviceSize kQuadIndexBytes = kIndicesPerQuad * sizeof(uint32_t);
    static constexpr VkDeviceSize kQuadTotalBytes = kQuadVertexBytes + kQuadIndexBytes;

    static constexpr VkDeviceSize VertexBytesOf(VkDeviceSize regionBytes) {
      return regionBytes * kQuadVertexBytes / kQuadTotalBytes;
    }

    VkDeviceSize vertexStagingOffset_ = 0;
    VkDeviceSize indexStagingOffset_ = 0;

    Vertex* vertexData_ = nullptr;
    uint32_t* indexData_ = nullptr;

    uint32_t vertexCapacity_ = 0;
    uint32_t indexCapacity_ = 0;

    uint32_t vertexOffset_ = 0;
    uint32_t indexOffset_ = 0;

    uint32_t vertexCount_ = 0;
    uint32_t indexCount_ = 0;
  };
  class StagingInfo {
   public:
    explicit StagingInfo(vkcore::BufferAllocator& bufferAllocator)
        : buffer_(bufferAllocator.Allocate(
              kBufferSize, VK_BUFFER_USAGE_TRANSFER_SRC_BIT,
              VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT)) {
      uint8_t* base = reinterpret_cast<uint8_t*>(buffer_.Map());

      constexpr VkDeviceSize kLayerSizes[] = {kSolidSize, kCutoutSize, kTranslucentSize};

      VkDeviceSize runningOffset = 0;
      for (uint32_t layer = 0; layer < kLayerCount; ++layer) {
        meshStreams_[layer] = MeshStream(base, runningOffset, kLayerSizes[layer]);
        runningOffset += kLayerSizes[layer];
      }
    }

    MeshStream& GetLayer(RenderLayer renderLayer) {
      return meshStreams_[static_cast<size_t>(renderLayer)];
    }
    const MeshStream& GetLayer(RenderLayer renderLayer) const {
      return meshStreams_[static_cast<size_t>(renderLayer)];
    }

    void AddTranslucentQuad(const glm::vec3& center, const std::array<uint32_t, 6>& indices) {
      TranslucentMesh::QuadEntry entry{};
      entry.center = center;
      for (size_t i = 0; i < 6; ++i) entry.indices[i] = indices[i];
      translucentQuadEntries_.push_back(entry);
    }

    const std::vector<TranslucentMesh::QuadEntry>& GetTranslucentQuads() const {
      return translucentQuadEntries_;
    }

    VkBuffer GetBufferHandle() const { return buffer_.GetHandle(); }

    void Reset() {
      for (auto& stream : meshStreams_) stream.Reset();
      translucentQuadEntries_.clear();
    }

    void CommitChunk() {
      for (auto& stream : meshStreams_) stream.CommitChunk();
      translucentQuadEntries_.clear();
    }

   private:
    static constexpr uint32_t kLayerCount = static_cast<uint32_t>(RenderLayer::Count);

    static constexpr VkDeviceSize kSolidSize = 12 * 1024 * 1024ull;
    static constexpr VkDeviceSize kCutoutSize = 8 * 1024 * 1024ull;
    static constexpr VkDeviceSize kTranslucentSize = 8 * 1024 * 1024ull;
    static constexpr VkDeviceSize kBufferSize = kSolidSize + kCutoutSize + kTranslucentSize;

    std::array<MeshStream, kLayerCount> meshStreams_;
    std::vector<TranslucentMesh::QuadEntry> translucentQuadEntries_;
    vkcore::BufferSlice buffer_;
  };

  bool BuildChunk(VkCommandBuffer cmd, StagingInfo& staging, const gm::ChunksMap& chunksMap,
                  const gm::Chunk& chunk);

  bool AddFace(StagingInfo& staging, uint32_t face, const glm::vec3& worldOffset,
               uint32_t surfaceId, const std::array<glm::vec4, 4>& cornerColors,
               RenderLayer renderLayer);

  std::optional<Mesh> MakeMeshLayer(VkCommandBuffer cmd, const StagingInfo& staging,
                                    RenderLayer renderLayer);
  std::optional<TranslucentMesh> MakeTranslucentMesh(VkCommandBuffer cmd, StagingInfo& staging);

 private:
  const vkcore::Device* device_;
  const gm::Lighting* lighting_;
  const gm::BlockManager* blockManager_;
  BlockRenderData* blockRenderData_;
  
  vkcore::MemoryAllocator memoryAllocator_;
  vkcore::BufferAllocator bufferAllocator_;

  std::vector<StagingInfo> stagingInfos_;
  std::vector<VkBufferMemoryBarrier> barriers_;
  uint32_t framesCount_;

};
}  // namespace gfx


