#pragma once

#include <glm/glm.hpp>

#include "../../../vkcore/resource/BufferAllocator.h"
#include "../../common/texture/MaterialManager.h"
#include "../../common/shader/ShaderCompiler.h"
#include "UiTypes.h"
#include "UiRenderPipeline.h"
#include "UiQuadInstance.h"

namespace gfx {
class UiRenderer {
 public:
  static constexpr float kNoBorder = -1.0f;

  struct PushData {
    glm::vec2 ndcScale;
  };

  UiRenderer(const vkcore::Device& device, vkcore::BufferAllocator& bufferAllocator,
             MaterialManager& materialManager,
             const vkcore::RenderPass& renderPass,
             const ShaderCompiler& shaderCompiler,
             const UiTextureRegion& blankTexture, uint32_t framesCount);

  void BeginFrame(VkCommandBuffer cmd, uint32_t currentFrame);

  void PushConstants(VkCommandBuffer cmd, const PushData& pushData) {
    pipeline_.GetLayout().PushConstants(
        cmd, VK_SHADER_STAGE_VERTEX_BIT, 0,
        {reinterpret_cast<const std::byte*>(&pushData), sizeof(PushData)});
  }
  void Submit(glm::vec2 pos, glm::vec2 size, const std::optional<UiTextureRegion>& texture,
              const glm::vec4& color, float radius = 0.0f, float borderWidth = kNoBorder);

  void SubmitGlyph(glm::vec2 pos, glm::vec2 size, const std::optional<GlyphSlot>& texture,
              const glm::vec4& color);
  void Render();

private:
  struct FrameData {
    vkcore::BufferSlice vertexBuffer;
    UiQuadInstance* mapped;

    FrameData(vkcore::BufferSlice&& vertexBuffer, UiQuadInstance* mapped)
        : vertexBuffer(std::move(vertexBuffer)), mapped(mapped) {}
  };

 private:
  static constexpr VkBufferUsageFlags kBufferUsage = VK_BUFFER_USAGE_VERTEX_BUFFER_BIT;
  static constexpr VkMemoryPropertyFlags kMemoryProperties =
      VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT;
  static constexpr VkDeviceSize kBufferSize = 32 * 1024 * 1024ull;
  static constexpr size_t kMaxInstances = kBufferSize / sizeof(UiQuadInstance);
  std::reference_wrapper<const vkcore::Device> device_;
  std::reference_wrapper<MaterialManager> materialManager_;
  UiRenderPipeline pipeline_;
  UiTextureRegion blankTexture_;
  std::vector<FrameData> frames_;
  uint32_t instanceOffset_ = 0;
  uint32_t instanceCount_ = 0;
  VkCommandBuffer cmd_ = VK_NULL_HANDLE;
  uint32_t currentFrame_ = 0;
  MaterialId bindedMaterial_ = kInvalidMaterialId;
};
}  // namespace gfx



// ========== src\gfx\render\ui\UiRenderPipeline.cpp ==========

#include "UiRenderPipeline.h"

#include <array>

#include "../../../core/PathPrefixes.h"
#include "UiQuadInstance.h"

namespace gfx {
vkcore::PipelineLayout UiRenderPipeline::BuildPipelineLayout(const vkcore::Device& device, const vkcore::DescriptorSetLayout& materialLayout) {
  VkPushConstantRange range = {};
  range.size = sizeof(PushConstant);
  range.stageFlags = VK_SHADER_STAGE_VERTEX_BIT;
  return vkcore::PipelineLayout(device, std::to_array({&materialLayout}), std::to_array({range}));
}

vkcore::Pipeline UiRenderPipeline::BuildPipeline(const vkcore::Device& device,
                                                 const vkcore::RenderPass& renderPass,
                                                 const ShaderCompiler& shaderCompiler) {
  vkcore::ShaderModule vert = CompileShaderModule(
      shaderCompiler, device, core::kShadersPrefix + "ui.vert", shaderc_vertex_shader);

  vkcore::ShaderModule frag = CompileShaderModule(
      shaderCompiler, device, core::kShadersPrefix + "ui.frag", shaderc_fragment_shader);

  return vkcore::GraphicsPipelineCreator(device)
    .AddShaderStage(vert, VK_SHADER_STAGE_VERTEX_BIT)
    .AddShaderStage(frag, VK_SHADER_STAGE_FRAGMENT_BIT)
    .AddVertexBinding(0, sizeof(UiQuadInstance), VK_VERTEX_INPUT_RATE_INSTANCE)
    .AddVertexAttribute(0, 0, VK_FORMAT_R32G32_SFLOAT, offsetof(UiQuadInstance, pos))
    .AddVertexAttribute(1, 0, VK_FORMAT_R32G32_SFLOAT, offsetof(UiQuadInstance, size))
    .AddVertexAttribute(2, 0, VK_FORMAT_R32G32B32A32_SFLOAT, offsetof(UiQuadInstance, uvRect))
    .AddVertexAttribute(3, 0, VK_FORMAT_R32G32B32A32_SFLOAT, offsetof(UiQuadInstance, color))
    .AddVertexAttribute(4, 0, VK_FORMAT_R32_SFLOAT, offsetof(UiQuadInstance, radius))
    .AddVertexAttribute(5, 0, VK_FORMAT_R32_SFLOAT, offsetof(UiQuadInstance, borderWidth))
    .AddVertexAttribute(6, 0, VK_FORMAT_R8_UINT, offsetof(UiQuadInstance, type))
    .SetDepthTest(false, false)
    .AddColorBlendAttachment(true)
    .AddDynamicState(VK_DYNAMIC_STATE_VIEWPORT)
    .AddDynamicState(VK_DYNAMIC_STATE_SCISSOR)
    .Build(pipelineLayout_.GetHandle(), renderPass.GetHandle());
}

UiRenderPipeline::UiRenderPipeline(const vkcore::Device& device,
                                   const vkcore::DescriptorSetLayout& materialLayout,
                                   const vkcore::RenderPass& renderPass,
                                   const ShaderCompiler& shaderCompiler)
    : pipelineLayout_(BuildPipelineLayout(device, materialLayout)),
      pipeline_(BuildPipeline(device, renderPass, shaderCompiler)) {}
}  // namespace gfx


