// ========== src\util\files.cpp ==========

#include "files.h"

#include <filesystem>
#include <fstream>

#if defined(__ANDROID__)
#include <android/asset_manager.h>
extern AAssetManager* g_AAssetManager;
#endif

namespace util {
namespace {

template <typename Container>
Container ReadFileImpl(std::string_view path) {
#if defined(__ANDROID__)
  AAsset* asset = AAssetManager_open(::g_AAssetManager, path.data(), AASSET_MODE_BUFFER);
  if (!asset) {
    return {};
  }

  const off_t length = AAsset_getLength(asset);
  Container buffer;
  buffer.resize(static_cast<size_t>(length));

  const int readBytes = AAsset_read(asset, buffer.data(), static_cast<size_t>(length));
  AAsset_close(asset);

  if (readBytes < 0 || static_cast<off_t>(readBytes) != length) {
    return {};
  }
  return buffer;
#else
  std::ifstream file(path.data(), std::ios::binary | std::ios::ate);
  if (!file) {
    return {};
  }

  const std::streamsize size = file.tellg();
  if (size < 0) {
    return {};
  }

  Container buffer = {};
  buffer.resize(static_cast<size_t>(size));

  file.seekg(0, std::ios::beg);
  if (!file.read(reinterpret_cast<char*>(buffer.data()), size)) {
    return {};
  }

  file.close();

  return buffer;
#endif
}

}  // namespace

std::vector<std::byte> ReadFileBytes(std::string_view path) {
  return ReadFileImpl<std::vector<std::byte>>(path);
}

std::string ReadFile(std::string_view path) { return ReadFileImpl<std::string>(path); }

std::vector<std::string> ListFiles(std::string_view dir) {
  std::vector<std::string> names;
#if defined(__ANDROID__)
  std::string path(dir);
  if (!path.empty() && path.back() == '/') path.pop_back();
  AAssetDir* d = AAssetManager_openDir(::g_AAssetManager, path.c_str());
  if (!d) return names;
  while (const char* name = AAssetDir_getNextFileName(d)) names.emplace_back(name);
  AAssetDir_close(d);
#else
  std::error_code ec;
  for (const auto& entry : std::filesystem::directory_iterator(std::string(dir), ec)) {
    if (entry.is_regular_file()) names.emplace_back(entry.path().filename().string());
  }
#endif
  return names;
}
}  // namespace util


