#pragma once

#include <algorithm>

#include "../common/SystemError.h"
#include "../common/UniqueHandles.h"
#include "LibraryLoader.h"

namespace vkcore {
class Instance {
 public:
  Instance(const LibraryLoader& loader, std::vector<std::string> extensions,
           std::vector<std::string> layers, const VkApplicationInfo& appInfo,
           VkInstanceCreateFlags instanceCreateFlags = 0);
  ~Instance() = default;

  template <typename T>
  [[nodiscard]] T* GetProcAddr(const LibraryLoader& loader, const char* fun) const {
    return reinterpret_cast<T*>(
        loader.GetDispatchTable().vkGetInstanceProcAddr(instance.get(), fun));
  }

  [[nodiscard]] const std::vector<std::string>& enabledExtensions() const { return enabledExtensions_; }

  [[nodiscard]] const std::vector<std::string> enabledLayers() const { return enabledLayers_; }

  [[nodiscard]] const InstanceDispatchTable& GetDispatchTable() const { return dispatchTable_; }

  [[nodiscard]] bool IsExtensionEnabled(const std::string& extension) const {
    return std::find(enabledExtensions_.begin(), enabledExtensions_.end(), extension) !=
           enabledExtensions_.end();
  }

  [[nodiscard]] VkInstance GetHandle() const { return instance.get(); }

 private:
  UniqueInstance instance = {};
  std::vector<std::string> enabledExtensions_ = {};
  std::vector<std::string> enabledLayers_ = {};
  uint32_t apiVersion = 0;
  InstanceDispatchTable dispatchTable_ = {};
};
}  // namespace vkcore


// ========== src\vkcore\instances\LibraryLoader.cpp ==========

#include "LibraryLoader.h"

namespace vkcore {

LibraryLoader::LibraryLoader() {
#ifdef _WIN32
  library_ = LoadLibraryA("vulkan-1.dll");
  if (!library_)
    throw std::runtime_error(
        "Failed to load vulkan library_ (vulkan-1.dll). "
        "Make sure Vulkan SDK or drivers are installed.");
#else
  library_ = dlopen("libvulkan.so.1", RTLD_LAZY);
  if (!library_) library_ = dlopen("libvulkan.so", RTLD_LAZY);
  if (!library_) library_ = dlopen("libvulkan.dylib", RTLD_LAZY);
  if (!library_) throw std::runtime_error("Failed to load vulkan library");
#endif

  loadBaseLibraryFunctions(library_, dispatchTable_);

  uint32_t extensionsCount = 0;
  VkResult result =
      dispatchTable_.vkEnumerateInstanceExtensionProperties(nullptr, &extensionsCount, nullptr);

  if (result != VK_SUCCESS)
    throw std::runtime_error("Failed to enumerate instance extension properties (count)");

  std::vector<VkExtensionProperties> extProperties(extensionsCount);
  result = dispatchTable_.vkEnumerateInstanceExtensionProperties(nullptr, &extensionsCount,
                                                                 extProperties.data());

  if (result != VK_SUCCESS)
    throw std::runtime_error("Failed to enumerate instance extension properties (data)");

  supportedInstanceExtensions_.reserve(extensionsCount);
  for (const auto& prop : extProperties) {
    supportedInstanceExtensions_.emplace_back(prop.extensionName);
  }

  uint32_t layersCount = 0;
  result = dispatchTable_.vkEnumerateInstanceLayerProperties(&layersCount, nullptr);

  if (result != VK_SUCCESS)
    throw std::runtime_error("Failed to enumerate instance layer properties (count)");

  std::vector<VkLayerProperties> layerProperties(layersCount);
  result = dispatchTable_.vkEnumerateInstanceLayerProperties(&layersCount, layerProperties.data());

  if (result != VK_SUCCESS)
    throw std::runtime_error("Failed to enumerate instance layer properties (data)");

  supportedInstanceLayers_.reserve(layersCount);
  for (const auto& prop : layerProperties) {
    supportedInstanceLayers_.emplace_back(prop.layerName);
  }

  for (const auto& layer : supportedInstanceLayers_) {
    uint32_t layerExtensionsCount = 0;

    result = dispatchTable_.vkEnumerateInstanceExtensionProperties(layer.c_str(),
                                                                   &layerExtensionsCount, nullptr);

    if (result != VK_SUCCESS)
      throw std::runtime_error("Failed to enumerate layer extension properties (count)");

    std::vector<VkExtensionProperties> layerExtensions(layerExtensionsCount);
    result = dispatchTable_.vkEnumerateInstanceExtensionProperties(
        layer.c_str(), &layerExtensionsCount, layerExtensions.data());

    if (result != VK_SUCCESS)
      throw std::runtime_error("Failed to enumerate layer extension properties (data)");

    auto& extensions = supportedLayerExtensions_[layer];
    extensions.reserve(layerExtensionsCount);

    for (const auto& extension : layerExtensions) {
      extensions.emplace_back(extension.extensionName);
    }
  }
}

LibraryLoader::~LibraryLoader() {
#ifdef _WIN32
  if (library_) {
    FreeLibrary(library_);
    library_ = nullptr;
  }
#else
  if (library_) {
    dlclose(library_);
    library_ = nullptr;
  }
#endif
}
}  // namespace vkcore


// ========== src\vkcore\instances\LibraryLoader.h ==========

#pragma once

#include <stdexcept>
#include <string_view>
#include <unordered_map>
#include <vector>

#ifdef _WIN32
#include <windows.h>
#else
#include <dlfcn.h>
#endif

#include "../common/vulkanFunctions.h"

namespace vkcore {

class LibraryLoader {
 public:
  LibraryLoader();
  ~LibraryLoader();

  [[nodiscard]] const LibraryDispatchTable& GetDispatchTable() const { return dispatchTable_; }

  [[nodiscard]] const std::vector<std::string>& supportedInstanceExtensions() const {
    return supportedInstanceExtensions_;
  }

  [[nodiscard]] const std::vector<std::string>& supportedInstanceLayers() const {
    return supportedInstanceLayers_;
  }

  [[nodiscard]] bool IsInstanceExtensionSupported(std::string_view extension) const {
    return std::find(supportedInstanceExtensions_.begin(), supportedInstanceExtensions_.end(),
                     extension) != supportedInstanceExtensions_.end();
  }

  [[nodiscard]] bool IsInstanceExtensionSupported(std::string_view extension,
                                                  const std::vector<std::string>& layers) const {
    if (IsInstanceExtensionSupported(extension)) return true;

    for (const auto& layer : layers) {
      const auto it = supportedLayerExtensions_.find(layer);
      if (it == supportedLayerExtensions_.end()) continue;

      const auto& extensions = it->second;
      if (std::find(extensions.begin(), extensions.end(), extension) != extensions.end())
        return true;
    }

    return false;
  }

 private:
#ifdef _WIN32
  HMODULE library_ = nullptr;
#else
  void* library_ = nullptr;
#endif

  LibraryDispatchTable dispatchTable_ = {};
  std::vector<std::string> supportedInstanceExtensions_;
  std::vector<std::string> supportedInstanceLayers_;
  std::unordered_map<std::string, std::vector<std::string>> supportedLayerExtensions_;
};

}  // namespace vkcore


// ========== src\vkcore\pipeline\Framebuffer.cpp ==========

#include "Framebuffer.h"

namespace vkcore {

Framebuffer::Framebuffer(const Device& device, std::span<const ImageView* const> attachments,
                         VkRenderPass renderPass, VkExtent2D extent, uint32_t layers,
                         VkFramebufferCreateFlags flags)
    : width_(extent.width),
      height_(extent.height),
      layers_(layers),
      flags_(flags),
      renderPass_(renderPass),
      attachments_(attachments.begin(), attachments.end()) {
  std::vector<VkImageView> viewHandles;
  viewHandles.reserve(attachments_.size());
  for (const ImageView* view : attachments_) {
    viewHandles.push_back(view->GetHandle());
  }

  VkFramebufferCreateInfo framebufferCI = {VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO};
  framebufferCI.flags = flags_;
  framebufferCI.renderPass = renderPass_;
  framebufferCI.attachmentCount = static_cast<uint32_t>(viewHandles.size());
  framebufferCI.pAttachments = viewHandles.data();
  framebufferCI.width = extent.width;
  framebufferCI.height = extent.height;
  framebufferCI.layers = layers_;

  VkFramebuffer rawFramebuffer = VK_NULL_HANDLE;
  VkResult result = device.GetDispatchTable().vkCreateFramebuffer(device.GetHandle(), &framebufferCI,
                                                               nullptr, &rawFramebuffer);
  if (result != VK_SUCCESS) {
    throw std::runtime_error("failed to create framebuffer");
  }

  FramebufferDeleter deleter{device.GetHandle(), device.GetDispatchTable().vkDestroyFramebuffer};
  framebuffer_ = UniqueFramebuffer(rawFramebuffer, deleter);
}

}  // namespace vkcore


