// ========== src\vkcore\pipeline\SubpassDescription.h ==========

#pragma once
#include <vulkan/vulkan.h>

#include <optional>
#include <vector>

namespace vkcore {

struct SubpassDescription {
  VkPipelineBindPoint bindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
  std::vector<VkAttachmentReference> colorRefs;
  std::vector<VkAttachmentReference> inputRefs;
  std::vector<VkAttachmentReference> resolveRefs;
  std::optional<VkAttachmentReference> depthStencilRef;
  std::vector<uint32_t> preserveIndices;

  [[nodiscard]] VkSubpassDescription Build() const {
    VkSubpassDescription desc = {};
    desc.pipelineBindPoint = bindPoint;
    desc.colorAttachmentCount = static_cast<uint32_t>(colorRefs.size());
    desc.pColorAttachments = colorRefs.empty() ? nullptr : colorRefs.data();
    desc.inputAttachmentCount = static_cast<uint32_t>(inputRefs.size());
    desc.pInputAttachments = inputRefs.empty() ? nullptr : inputRefs.data();
    desc.pResolveAttachments = resolveRefs.empty() ? nullptr : resolveRefs.data();
    desc.pDepthStencilAttachment = depthStencilRef.has_value() ? &depthStencilRef.value() : nullptr;
    desc.preserveAttachmentCount = static_cast<uint32_t>(preserveIndices.size());
    desc.pPreserveAttachments = preserveIndices.empty() ? nullptr : preserveIndices.data();
    return desc;
  }
};

}  // namespace vkcore



// ========== src\vkcore\present\Surface.cpp ==========

#include "Surface.h"

namespace vkcore {

#ifdef VK_USE_PLATFORM_ANDROID_KHR

Surface::Surface(const Instance& instance, ANativeWindow* window) : instance_(&instance) {
  if (!window) {
    throw std::runtime_error("Surface: ANativeWindow* is null");
  }

  const auto& dispatchTable = instance_->GetDispatchTable();

  if (!dispatchTable.androidSurfaceTable.has_value()) {
    throw std::runtime_error("Surface: AndroidSurfaceDispatchTable not loaded");
  }

  const auto& androidTable = dispatchTable.androidSurfaceTable.value();
  if (!androidTable.vkCreateAndroidSurfaceKHR) {
    throw std::runtime_error("Surface: vkCreateAndroidSurfaceKHR is null");
  }

  VkAndroidSurfaceCreateInfoKHR surfaceCI = {VK_STRUCTURE_TYPE_ANDROID_SURFACE_CREATE_INFO_KHR};
  surfaceCI.window = window;

  VkSurfaceKHR surfaceRaw = VK_NULL_HANDLE;
  VkResult result =
      androidTable.vkCreateAndroidSurfaceKHR(instance_->GetHandle(), &surfaceCI, nullptr, &surfaceRaw);
  SystemError::Check(result, "Surface: vkCreateAndroidSurfaceKHR failed");

  SetupDeleter(surfaceRaw);
}

#else

Surface::Surface(const Instance& instance, GLFWwindow* window) : instance_(&instance) {
  if (!window) {
    throw std::runtime_error("Surface: GLFWwindow* is null");
  }

  VkSurfaceKHR surfaceRaw = VK_NULL_HANDLE;
  VkResult result = glfwCreateWindowSurface(instance_->GetHandle(), window, nullptr, &surfaceRaw);
  SystemError::Check(result, "Surface: glfwCreateWindowSurface failed");

  SetupDeleter(surfaceRaw);
}

#endif

void Surface::SetupDeleter(VkSurfaceKHR surfaceRaw) {
  const auto& dispatchTable = instance_->GetDispatchTable();

  if (!dispatchTable.surfaceTable.has_value()) {
    throw std::runtime_error("Surface: SurfaceDispatchTable not loaded");
  }

  const auto& surfaceTable = dispatchTable.surfaceTable.value();

  SurfaceDeleter deleter = {};
  deleter.instance = instance_->GetHandle();
  deleter.func = surfaceTable.vkDestroySurfaceKHR;

  surface_ = UniqueSurfaceKHR(surfaceRaw, deleter);
}

VkSurfaceKHR Surface::GetHandle() const noexcept { return surface_.get(); }

const Instance& Surface::getInstance() const noexcept { return *instance_; }

}  // namespace vkcore


