// ========== src\vkcore\resource\MemoryAllocator.cpp ==========

#include "MemoryAllocator.h"

#include <algorithm>
#include <stdexcept>

namespace vkcore {

MemoryAllocator::MemoryAllocator(const Device& device) : device_(&device) {}

std::optional<MemorySlice> MemoryAllocator::Allocate(VkDeviceSize size, VkDeviceSize alignment,
                                                     uint32_t memoryTypeBits,
                                                     VkMemoryPropertyFlags flags) {
  std::optional<uint32_t> memoryTypeIndex =
      device_->getPhysicalDevice().findMemoryType(flags, memoryTypeBits);
  if (!memoryTypeIndex.has_value()) throw std::runtime_error("failed to find suitable memory type");
  std::vector<std::unique_ptr<MemoryBlock>>& blocks = blocksByType_[*memoryTypeIndex];

  for (auto& block : blocks) {
    if (auto slice = block->reserve(size, alignment)) {
      return slice;
    }
  }

  VkDeviceSize minBlockSize = (flags & VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT)
                                  ? VKCORE_MEMORY_BLOCK_MIN_SIZE_HOST_VISIBLE
                                  : VKCORE_MEMORY_BLOCK_MIN_SIZE_DEVICE_LOCAL;

  VkDeviceSize blockSize = std::max(VKCORE_MEMORY_BLOCK_GROWTH(size), minBlockSize);

  auto newBlock = std::make_unique<MemoryBlock>(*device_, blockSize, flags, *memoryTypeIndex);

  auto slice = newBlock->reserve(size, alignment);

  blocks.push_back(std::move(newBlock));

  return slice;
}

}  // namespace vkcore


// ========== src\vkcore\resource\MemoryAllocator.h ==========

#pragma once

#include <vulkan/vulkan.h>

#include <memory>
#include <optional>
#include <unordered_map>
#include <vector>

#include "../devices/Device.h"
#include "DeviceMemory.h"
#include "MemoryBlock.h"

namespace vkcore {

#define VKCORE_MEMORY_BLOCK_GROWTH(size) ((size)*3 / 2)

#define VKCORE_MEMORY_BLOCK_MIN_SIZE_HOST_VISIBLE (32ull * 1024 * 1024)
#define VKCORE_MEMORY_BLOCK_MIN_SIZE_DEVICE_LOCAL (64ull * 1024 * 1024)

class MemoryAllocator {
 public:
  explicit MemoryAllocator(const Device& device);

  std::optional<MemorySlice> Allocate(VkDeviceSize size, VkDeviceSize alignment,
                                      uint32_t memoryTypeBits, VkMemoryPropertyFlags flags);

 private:
  const Device* device_;
  std::unordered_map<uint32_t, std::vector<std::unique_ptr<MemoryBlock>>> blocksByType_;
};

}  // namespace vkcore


// ========== src\vkcore\resource\MemoryBindHelper.h ==========

#pragma once

#include <stdexcept>

#include "../devices/Device.h"
#include "MemoryAllocator.h"
#include "MemoryBlock.h"

namespace vkcore::detail {

template <typename Resource>
static MemorySlice reserveDedicated(Resource& resource, const Device& device,
                                    VkMemoryPropertyFlags flags) {
  const VkMemoryRequirements& req = resource.memoryRequirements();

  std::optional<uint32_t> memoryTypeIndex =
      device.getPhysicalDevice().findMemoryType(flags, req.memoryTypeBits);

  if (!memoryTypeIndex)
    throw SystemError(VK_ERROR_UNKNOWN, "failed to find a suitable memory type index");

  MemoryBlock block(device, req.size, flags, *memoryTypeIndex);
  auto slice = block.reserve(req.size, req.alignment);

  if (!slice) throw std::runtime_error("reserveDedicated: failed to reserve memory");

  return std::move(*slice);
}

template <typename Resource>
static MemorySlice reservePooled(Resource& resource, MemoryAllocator& allocator,
                                 VkMemoryPropertyFlags flags) {
  const VkMemoryRequirements& req = resource.memoryRequirements();
  auto slice = allocator.Allocate(req.size, req.alignment, req.memoryTypeBits, flags);

  if (!slice) throw std::runtime_error("reservePooled: failed to reserve memory");

  return std::move(*slice);
}

}  // namespace vkcore::detail


// ========== src\vkcore\resource\MemoryBlock.cpp ==========

#include "MemoryBlock.h"

namespace vkcore {

MemoryBlock::MemoryBlock(const Device& device, VkDeviceSize size, VkMemoryPropertyFlags flags,
                         uint32_t memoryTypeIndex) {
  storage_ = std::make_shared<MemoryBlockStorage>(DeviceMemory(device, size, memoryTypeIndex),
                                                  FreeListAllocator(size));
}

std::optional<MemorySlice> MemoryBlock::reserve(VkDeviceSize size, VkDeviceSize alignment) {
  if (!storage_) {
    return std::nullopt;
  }

  auto region = storage_->allocator.Allocate(size, alignment);

  if (!region) {
    return std::nullopt;
  }

  return MemorySlice(storage_, *region);
}

std::optional<MemorySlice> MemoryBlock::reserveFull() {
  if (!storage_) {
    return std::nullopt;
  }

  auto region = storage_->allocator.reserveFull();

  if (!region) {
    return std::nullopt;
  }

  return MemorySlice(storage_, *region);
}

}  // namespace vkcore


// ========== src\vkcore\resource\MemoryBlock.h ==========

#pragma once

#include <vulkan/vulkan.h>

#include <memory>
#include <optional>

#include "../devices/Device.h"
#include "DescriptorSet.h"
#include "DeviceMemory.h"
#include "FreeListAllocator.h"

namespace vkcore {

struct MemoryBlockStorage {
  DeviceMemory memory = DeviceMemory({}, 0, 0);
  FreeListAllocator allocator;

  MemoryBlockStorage(DeviceMemory&& memory, FreeListAllocator&& allocator)
      : memory(std::move(memory)), allocator(std::move(allocator)) {}
};

class MemorySlice {
 public:
  MemorySlice(std::shared_ptr<MemoryBlockStorage> storage, const FreeListAllocator::Region& region)
      : storage_(std::move(storage)), region_(region) {}

  ~MemorySlice() { release(); }

  MemorySlice(const MemorySlice&) = delete;
  MemorySlice& operator=(const MemorySlice&) = delete;

  MemorySlice(MemorySlice&& other) noexcept
      : storage_(std::move(other.storage_)), region_(other.region_) {
    other.storage_.reset();
  }

  MemorySlice& operator=(MemorySlice&& other) noexcept {
    if (this != &other) {
      release();

      storage_ = std::move(other.storage_);
      region_ = other.region_;

      other.storage_.reset();
    }

    return *this;
  }

  [[nodiscard]] VkDeviceMemory memory() const {
    return storage_ ? storage_->memory.GetHandle() : VK_NULL_HANDLE;
  }

  [[nodiscard]] void* map(VkDeviceSize offset = 0) const {
    if (!storage_) {
      return nullptr;
    }

    return storage_->memory.map(region_.offset + offset);
  }

  [[nodiscard]] VkDeviceSize offset() const { return region_.offset; }

  [[nodiscard]] VkDeviceSize size() const { return region_.size; }

 private:
  void release() {
    if (storage_) {
      storage_->allocator.Free(region_);
      storage_.reset();
    }
  }

  std::shared_ptr<MemoryBlockStorage> storage_;
  FreeListAllocator::Region region_;
};

class MemoryBlock {
 public:
  MemoryBlock(const Device& device, VkDeviceSize size, VkMemoryPropertyFlags flags,
              uint32_t memoryTypeIndex);

  [[nodiscard]] std::optional<MemorySlice> reserve(VkDeviceSize size, VkDeviceSize alignment = 1);

  [[nodiscard]] std::optional<MemorySlice> reserveFull();

  [[nodiscard]] DeviceMemory& deviceMemory() const { return storage_->memory; }

 private:
  const Device* device_;
  std::shared_ptr<MemoryBlockStorage> storage_;
};

}  // namespace vkcore


